### 2. Implementation

```ts
// parseDuration.ts
export function parseDuration(s: string): number {
  const match = /^([0-9]+h)?([0-9]+m)?([0-9]+s)?(?![\s\S])/.exec(s);

  if (!match || s.length === 0) {
    throw new SyntaxError(`Invalid duration: ${JSON.stringify(s)}`);
  }

  const [, hours, minutes, seconds] = match;
  const value = (part: string | undefined): number =>
    part === undefined ? 0 : Number(part.slice(0, -1));

  const total = value(hours) * 3600 + value(minutes) * 60 + value(seconds);

  if (!Number.isSafeInteger(total)) {
    throw new RangeError("Duration exceeds the safe integer range");
  }

  return total;
}
```

The final `(?![\s\S])` requires the actual end of the string. In JavaScript, `$` can also match before a final newline, which would incorrectly accept `"1h\n"`.

