```ts
export function parseDuration(s: string): number {
  if (s.length === 0) {
    throw new SyntaxError("Duration cannot be empty");
  }

  const token = /([0-9]+)([hms])/y;
  let total = 0;

  while (token.lastIndex < s.length) {
    const offset = token.lastIndex;
    const match = token.exec(s);

    if (match === null) {
      throw new SyntaxError(`Invalid duration at offset ${offset}`);
    }

    const unit = match[2];
    const secondsPerUnit = unit === "h" ? 3600 : unit === "m" ? 60 : 1;
    total += Number(match[1]) * secondsPerUnit;

    if (!Number.isSafeInteger(total)) {
      throw new RangeError("Duration exceeds the safe integer range");
    }
  }

  return total;
}
```

