export function parseDuration(s: string): number {
  const match = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/.exec(s);

  // Compare the full match because `$` can match before a final newline.
  if (s.length === 0 || !match || match[0] !== s) {
    throw new SyntaxError(`Invalid duration: ${JSON.stringify(s)}`);
  }

  const [, hours = "0", minutes = "0", seconds = "0"] = match;
  const total = Number(hours) * 3600 + Number(minutes) * 60 + Number(seconds);

  if (!Number.isSafeInteger(total)) {
    throw new RangeError("Duration exceeds the safe integer range in seconds");
  }

  return total;
}
```

